def min_possible_abs_destination():
    import sys
    input = sys.stdin.read
    data = input().strip()
    X, K, D = map(int, data.split())

    # Calculate the net effect of K moves
    net_effect = K % 2

    # If K is even, we can always return to the original position
    if net_effect == 0:
        return abs(X)

    # If K is odd, we need to consider the parity of X
    # If X is even, we can make one move in the negative direction
    # If X is odd, we can make one move in the positive direction
    if X % 2 == 0:
        return min(abs(X - D), abs(X + D))
    else:
        return min(abs(X + D), abs(X - D))

min_possible_abs_destination()
